mapper.select:
select t.pre_fee_id preFeeId,t.community_id communityId,t.fee_id feeId,pfc.fee_name feeName,pf.owner_name ownerName,
pf.owner_id ownerId,pf.payer_obj_id payerObjId,
pf.payer_obj_name payerObjName,pf.payer_obj_type payerObjType,pf.owe_amount oweAmount,pf.receivable_amount receivableAmount,
pf.start_time startTime,pf.end_time endTime
from pay_fee_sub t
left join pay_fee pf on t.fee_id = pf.fee_id
left join pay_fee_config pfc on pf.config_id = pfc.config_id
where 1 =1

    and t.pre_fee_id= #{preFeeId}


    and t.community_id= #{communityId}


    and t.fee_id= #{feeId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update pay_fee_sub t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.pre_fee_id= #{preFeeId}


where 1=1

    and t.fee_id= #{feeId}


    and t.community_id= #{communityId}

mapper.select:
